// Init Factory — run context + typed config for the Reel Factory (same viral_config table as Discovery).
// Missing keys fall back to DEFAULTS, so deleting a row never breaks the run.

const DEFAULTS = {
  factory_platforms: 'twitch',
  factory_allowed_rights: 'ALLOWED,ALLOWED_CC,DISCOVERY_ONLY',
  factory_max_reels_per_day: 3,
  factory_ready_buffer_max: 3,
  factory_creator_cooldown_h: 12,
  eligible_score_min: 60,
  eligible_max_age_h: 48,
  twitch_eligible_max_age_h: 72,
  tts_voice: 'am_adam',
  tts_speed: 1.05,
  media_worker_url: '',
  factory_force_candidate_key: '',
  llm_model: 'claude-opus-5-5',
  llm_effort: 'medium',
  ig_handle: '',
  publish_max_per_day: 1,
  factory_min_views: 250,
  factory_full_captions_sources: '',
  factory_text_style: 'meme',
  factory_voice_ratio: 0.5,
  factory_max_segment_s: 60,
};
const LIST_KEYS = ['factory_platforms', 'factory_allowed_rights', 'factory_full_captions_sources'];

const warnings = [];
const config = { ...DEFAULTS };
for (const item of $input.all()) {
  const r = item.json;
  const key = String(r.key ?? '').trim();
  if (!(key in DEFAULTS)) continue; // Discovery keys are ignored here
  const hasNum = r.value_number !== null && r.value_number !== undefined && Number.isFinite(Number(r.value_number));
  const hasStr = typeof r.value_string === 'string' && r.value_string.trim() !== '';
  if (typeof DEFAULTS[key] === 'number') {
    const v = hasNum ? Number(r.value_number) : (hasStr ? Number(r.value_string) : NaN);
    if (Number.isFinite(v)) config[key] = v;
    else warnings.push(`key "${key}" has no valid number: default ${DEFAULTS[key]} used`);
  } else if (hasStr) {
    config[key] = r.value_string.trim();
  }
}

for (const key of LIST_KEYS) {
  config[key] = String(config[key] ?? '').split(',').map(s => s.trim()).filter(Boolean);
}
config.factory_platforms = config.factory_platforms.map(s => s.toLowerCase());
config.factory_allowed_rights = config.factory_allowed_rights.map(s => s.toUpperCase());
config.media_worker_url = String(config.media_worker_url).replace(/\/+$/, '');
if (!config.media_worker_url) warnings.push('media_worker_url missing: rendering will fail');
config.factory_text_style = config.factory_text_style === 'hook' ? 'hook' : 'meme';
config.factory_voice_ratio = Math.min(1, Math.max(0, Number(config.factory_voice_ratio) || 0));
config.factory_max_segment_s = Math.min(75, Math.max(15, Number(config.factory_max_segment_s) || 60));

const now = new Date();
return [{
  json: {
    run_id: `fact-${$now.toFormat('yyyyMMdd-HHmm')}-${$execution.id}`,
    workflow: '02 - US VIRAL | Reel Factory',
    started_at: now.toISOString(),
    started_at_ms: now.getTime(),
    config_warnings: warnings,
    config,
  },
}];

// Pick Candidate — decides whether to produce a Reel now and which ELIGIBLE candidate to use.
// Pure rules, no AI:
//  - stop if the daily cap or the READY buffer is reached;
//  - keep only allowed platforms / rights, skip candidates already used in viral_posts;
//  - skip creators used within the cooldown;
//  - best trend_score wins (ties: newer first).
// Returns 1 item (the pick) or 0 items (nothing to do: the chain stops silently).

const run = $('Init Factory').first().json;
const cfg = run.config;
const nowMs = run.started_at_ms;

const posts = $('Get Recent Posts').all().map(i => i.json ?? {}).filter(p => p.post_key);
const ageH = iso => (nowMs - Date.parse(iso ?? '')) / 3.6e6;

// Test posts (forced by hand) never count toward the caps
const isTest = p => String(p.status_reason ?? '').startsWith('forced');
const last24 = posts.filter(p => !isTest(p) && ageH(p.created_at) <= 24 && !['FAILED', 'SKIPPED'].includes(p.status));
const ready = posts.filter(p => !isTest(p) && p.status === 'READY');
// Produce at most what the Publisher can post (+1 spare): no Reels rendered just to go STALE
const dayCap = Math.min(cfg.factory_max_reels_per_day, cfg.publish_max_per_day + 1);
const bufferCap = Math.min(cfg.factory_ready_buffer_max, cfg.publish_max_per_day + 1);
const usedKeys = new Set(posts.map(p => p.candidate_key));
const recentCreators = new Set(
  posts.filter(p => p.status !== 'FAILED' && ageH(p.created_at) <= cfg.factory_creator_cooldown_h)
    .map(p => (p.creator_name ?? '').toLowerCase()),
);

const stats = {
  posts_last_24h: last24.length,
  ready_buffer: ready.length,
  eligible_total: 0,
  skipped: { platform: 0, rights: 0, already_used: 0, creator_cooldown: 0, too_old: 0, low_views: 0 },
};

// Manual test override: viral_config.factory_force_candidate_key picks that candidate once (any status, no caps).
const force = cfg.factory_force_candidate_key;
// Once used (or not found) it is ignored and the normal rules apply.
const forced = force && !usedKeys.has(force)
  ? $input.all().map(i => i.json ?? {}).find(x => x.candidate_key === force)
  : null;
if (forced) {
  return [{ json: { run_id: run.run_id, post_key: `post-${forced.platform}-${forced.content_id}`, candidate: forced, pick_reason: 'forced by factory_force_candidate_key', runner_up: null, stats } }];
}

if (last24.length >= dayCap) {
  console.log(`daily cap reached (${last24.length}/${dayCap})`, stats);
  return [];
}
if (ready.length >= bufferCap) {
  console.log(`READY buffer full (${ready.length}/${bufferCap})`, stats);
  return [];
}

const pool = [];
for (const it of $input.all()) {
  const c = it.json ?? {};
  if (!c.candidate_key || c.status !== 'ELIGIBLE') continue;
  stats.eligible_total++;
  if (!cfg.factory_platforms.includes(String(c.platform).toLowerCase())) { stats.skipped.platform++; continue; }
  if (!cfg.factory_allowed_rights.includes(String(c.rights_status).toUpperCase())) { stats.skipped.rights++; continue; }
  if (usedKeys.has(c.candidate_key)) { stats.skipped.already_used++; continue; }
  if (recentCreators.has((c.creator_name ?? '').toLowerCase())) { stats.skipped.creator_cooldown++; continue; }
  const maxAgeH = c.platform === 'twitch' ? cfg.twitch_eligible_max_age_h : cfg.eligible_max_age_h;
  if (ageH(c.published_at) > maxAgeH) { stats.skipped.too_old++; continue; }
  if ((Number(c.views) || 0) < cfg.factory_min_views) { stats.skipped.low_views++; continue; }
  pool.push(c);
}

pool.sort((a, b) => (b.trend_score - a.trend_score) || (Date.parse(b.published_at) - Date.parse(a.published_at)));
if (pool.length === 0) {
  console.log('no usable ELIGIBLE candidate', stats);
  return [];
}

const pick = pool[0];
return [{
  json: {
    run_id: run.run_id,
    post_key: `post-${pick.platform}-${pick.content_id}`,
    candidate: pick,
    pick_reason: `best of ${pool.length} usable (score ${pick.trend_score})`,
    runner_up: pool[1] ? { candidate_key: pool[1].candidate_key, trend_score: pool[1].trend_score } : null,
    stats,
  },
}];

// Build LLM Request — the ONE Claude call per Reel. Sends clip facts + timestamped transcript,
// asks for strict JSON (segment, intro voice-over, hook, meme line, caption, hashtags, skip flag).

const run = $('Init Factory').first().json;
const cfg = run.config;
const pick = $('Pick Candidate').first().json;
const c = pick.candidate;
const tr = $('Get Transcribe Job').last().json.result ?? {};
const duration = Number(tr.duration) || Number(c.duration_seconds) || 0;

const lines = (tr.segments ?? [])
  .map(s => `[${Number(s.start).toFixed(1)}-${Number(s.end).toFixed(1)}] ${String(s.text ?? '').trim()}`)
  .join('\n')
  .slice(0, 6000);

const system = [
  'You package viral clips for an English-language Instagram Reels page (US audience) about streamers, YouTubers and viral internet moments.',
  'The Reel: the clip plays from the first frame with a short meme-style line above it for the whole video (or a big hook for the first seconds); sometimes our narrator speaks a short intro over its first seconds (original audio quieter underneath).',
  'Our commentary must add context, not repeat the clip. Viewers decide in the first 2 seconds whether to keep watching.',
  'Rules:',
  `- segment_start/segment_end: seconds inside the clip, one continuous moment. Usually 12-30 seconds; up to ${cfg.factory_max_segment_s} seconds only when the build-up is part of the fun (a whole funny exchange, a story that pays off). Cut dead air, start right at the setup, end right after the payoff or the best reaction, never in the middle of a sentence (use the transcript timestamps). Use the whole clip only if every second earns its place.`,
  '- intro_script: ONE sentence, 8-16 words (about 4 seconds spoken). Who it is and why this moment matters. Natural and punchy, no hashtags, no emojis, no questions, never invent facts not supported by the title or transcript.',
  '- hook: max 6 words, creates curiosity without giving away the payoff, specific to this clip (name the streamer when it helps), no emojis, no quotes, never misleading or clickbait about something that does not happen.',
  '- meme_caption: 2-6 words shown above the clip for the whole video, like a TikTok/Instagram meme page overlay: an ironic, relatable reaction that frames how to watch it, not a description and not a spoiler. Mostly lowercase, casual internet English, no emojis, no hashtags, no quotes. Style examples (do not copy): "grown men btw", "1% scary 99% funny", "he was NOT ready", "chat saw everything", "bro thought he had it".',
  '- emphasis_at: the second (in the clip timeline, between segment_start and segment_end) of the single strongest moment: the punchline, reaction or payoff. A punch zoom is placed there.',
  '- caption: Instagram caption, 1-3 short lines, ends with a question that invites comments, at most 2 emojis, no hashtags, no links.',
  '- hashtags: 5-8 relevant tags, lowercase, letters/numbers only, without #.',
  '- skip=true (with a short skip_reason) if the clip is unusable: no understandable moment, mostly silence or music, sexual content, hate speech or slurs as the point of the clip, minors at risk, doxxing, real violence. Otherwise skip=false and skip_reason="".',
].join('\n');

const user = [
  `Creator: ${c.creator_name} (Twitch)`,
  `Clip title: ${c.title}`,
  `Clip created: ${c.published_at} | views: ${c.views} | duration: ${duration.toFixed(1)}s`,
  'Transcript with timestamps (seconds):',
  lines || '(no speech detected)',
].join('\n');

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['skip', 'skip_reason', 'segment_start', 'segment_end', 'emphasis_at', 'intro_script', 'hook', 'meme_caption', 'caption', 'hashtags'],
  properties: {
    skip: { type: 'boolean' },
    skip_reason: { type: 'string' },
    segment_start: { type: 'number' },
    segment_end: { type: 'number' },
    emphasis_at: { type: 'number' },
    intro_script: { type: 'string' },
    hook: { type: 'string' },
    meme_caption: { type: 'string' },
    caption: { type: 'string' },
    hashtags: { type: 'array', items: { type: 'string' } },
  },
};

// Claude Messages API: structured output (output_config.format) guarantees schema-valid JSON;
// thinking stays on (adaptive) and effort sets its depth. fallbacks: "default" re-runs a declined
// request on Anthropic's recommended fallback model instead of returning a refusal.
return [{
  json: {
    duration,
    body: {
      model: cfg.llm_model,
      max_tokens: 8000,
      system,
      messages: [{ role: 'user', content: user }],
      output_config: { effort: cfg.llm_effort, format: { type: 'json_schema', schema } },
      fallbacks: 'default',
    },
  },
}];

// Parse Script — validates the model JSON and turns it into safe render inputs.
// Never trusts the model blindly: segment clamped to the clip, text trimmed, hashtags cleaned.
// Output: one item with `skip` true/false and the fields to store in viral_posts.

const cfg = $('Init Factory').first().json.config;
const pick = $('Pick Candidate').first().json;
const c = pick.candidate;
const req = $('Build LLM Request').first().json;
const res = $input.first().json;
const duration = req.duration || 30;

const clean = (s, max) => String(s ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const tokens = res.usage ? (res.usage.input_tokens ?? 0) + (res.usage.output_tokens ?? 0) : null;
const out = { post_key: pick.post_key, candidate_id: c.id, llm_model: res.model ?? req.body.model, llm_tokens: tokens };

if (res.error) {
  return [{ json: { ...out, skip: true, skip_reason: `llm_error: ${clean(res.error.message ?? res.error, 200)}`, llm_failed: true } }];
}
if (res.stop_reason === 'refusal') {
  return [{ json: { ...out, skip: true, skip_reason: `llm_refusal: ${clean(res.stop_details?.category ?? '', 60)}` } }];
}

// Thinking blocks come first; the JSON answer is the text block
let data;
try {
  data = JSON.parse((res.content ?? []).find(b => b.type === 'text')?.text ?? '');
} catch (e) {
  return [{ json: { ...out, skip: true, skip_reason: 'llm_invalid_json', llm_failed: true } }];
}

if (data.skip) return [{ json: { ...out, skip: true, skip_reason: `llm_skip: ${clean(data.skip_reason, 200)}` } }];

// Segment: inside the clip, at least 5s (else the whole clip), at most factory_max_segment_s
let start = Math.max(0, Number(data.segment_start) || 0);
let end = Math.min(duration, Number(data.segment_end) || duration);
if (!(end - start >= 5)) { start = 0; end = duration; }
if (end - start > cfg.factory_max_segment_s) end = start + cfg.factory_max_segment_s;

const hashtags = [...new Set((data.hashtags ?? [])
  .map(h => String(h).toLowerCase().replace(/[^a-z0-9]/g, ''))
  .filter(h => h.length >= 2 && h.length <= 30))].slice(0, 8);

// Punch zoom: model gives clip time, the worker wants seconds from the segment start
const emph = Number(data.emphasis_at) - start;
const emphasisAt = Number.isFinite(emph) && emph >= 0.5 && emph <= end - start - 0.3 ? Math.round(emph * 10) / 10 : null;

const intro = clean(data.intro_script, 160);
const hook = clean(data.hook, 48).replace(/["“”]/g, '');
// Meme line: plain text only (the render font has no colour emojis)
const meme = clean(String(data.meme_caption ?? '').replace(/[^\p{L}\p{N}\s%.,!?'’&+\-:\/#@$]/gu, ''), 48).replace(/["“”]/g, '');
// Style: meme line for the whole Reel (or hook), our voice on a share of the Reels (A/B test)
const textStyle = cfg.factory_text_style === 'meme' && meme ? 'meme' : 'hook';
const voice = Math.random() < cfg.factory_voice_ratio;
const credit = `twitch.tv/${String(c.source_key ?? '').replace(/^twitch:/, '') || c.creator_name}`;
const caption = [
  clean(data.caption, 600),
  '',
  `🎥 ${c.creator_name} on Twitch`,
  '',
  hashtags.map(h => `#${h}`).join(' '),
].join('\n').trim();

if (!intro || !hook) return [{ json: { ...out, skip: true, skip_reason: 'llm_empty_fields', llm_failed: true } }];

return [{
  json: {
    ...out,
    skip: false,
    segment_start: Math.round(start * 10) / 10,
    segment_end: Math.round(end * 10) / 10,
    emphasis_at: emphasisAt,
    intro_script: intro,
    hook,
    meme_caption: meme,
    text_style: textStyle,
    voice,
    style_variant: `${textStyle}+${voice ? 'voice' : 'novoice'}`,
    caption,
    hashtags: hashtags.join(' '),
    credit,
  },
}];

// Collect Result — one item per post still RENDERING: was its render finished in the meantime?
// done -> READY, failed (or stuck for more than MAX_RENDER_MIN) -> FAILED, otherwise left as it is.
// Renders can outlive a run (n8n Cloud stops executions after 5 min): this picks them up next hour.

const MAX_RENDER_MIN = 45;
const posts = $('Get Pending Renders').all();

return $input.all().map((it, i) => {
  const job = it.json ?? {};
  const post = posts[i]?.json ?? {};
  const ageMin = (Date.now() - Date.parse(post.updated_at ?? '')) / 60000;
  let outcome = 'running';
  let error = null;
  if (job.status === 'done') outcome = 'done';
  else if (job.status === 'failed') { outcome = 'failed'; error = job.error ?? 'render failed'; }
  else if (ageMin > MAX_RENDER_MIN) {
    outcome = 'failed';
    error = job.status ? `render stuck in ${job.status} for ${Math.round(ageMin)} min` : `worker unreachable for ${Math.round(ageMin)} min`;
  }
  return {
    json: {
      post_key: post.post_key,
      candidate_key: post.candidate_key,
      outcome,
      video_url: job.result?.video_url ?? null,
      cover_url: job.result?.cover_url ?? null,
      duration: job.result?.duration ?? null,
      error: error ? String(error).slice(0, 1000) : null,
    },
  };
});
